/* gfo_transpile.c */
#include "gfo_transpile.h"

static void putc1(gfo_out* o, char c){
  if(o->len + 1 >= o->cap) return;
  o->buf[o->len++] = c;
  o->buf[o->len] = '\0';
}

void gfo_out_init(gfo_out* o, char* buf, gfo_u32 cap){
  o->buf = buf; o->cap = cap; o->len = 0;
  if(cap) buf[0]='\0';
}
void gfo_out_puts(gfo_out* o, const char* s){
  while(*s){ putc1(o, *s++); }
}
void gfo_out_put_u32(gfo_out* o, gfo_u32 v){
  char tmp[16];
  int i=0, j;
  if(v==0){ putc1(o,'0'); return; }
  while(v>0 && i<15){ tmp[i++] = (char)('0' + (v%10)); v/=10; }
  for(j=i-1;j>=0;j--) putc1(o, tmp[j]);
}
void gfo_out_put_str_lit(gfo_out* o, gfo_str s){
  gfo_u16 i;
  putc1(o,'"');
  for(i=0;i<s.len;i++){
    char c = s.ptr[i];
    if(c=='"' || c=='\\'){ putc1(o,'\\'); putc1(o,c); }
    else if(c=='\n'){ putc1(o,'\\'); putc1(o,'n'); }
    else if(c=='\r'){ putc1(o,'\\'); putc1(o,'r'); }
    else if(c=='\t'){ putc1(o,'\\'); putc1(o,'t'); }
    else { putc1(o,c); }
  }
  putc1(o,'"');
}

static void emit_value(gfo_out* o, gfo_value v){
  gfo_out_puts(o, "{");
  /* type */
  gfo_out_puts(o, ".t=");
  gfo_out_put_u32(o, (gfo_u32)v.t);
  gfo_out_puts(o, ",.v={");
  if(v.t==GFO_VAL_I32){
    if(v.v.i < 0){ putc1(o,'-'); gfo_out_put_u32(o, (gfo_u32)(-v.v.i)); }
    else gfo_out_put_u32(o, (gfo_u32)v.v.i);
  } else if(v.t==GFO_VAL_BOOL){
    gfo_out_put_u32(o, v.v.b);
  } else if(v.t==GFO_VAL_STR || v.t==GFO_VAL_PATH || v.t==GFO_VAL_SYM){
    /* just emit placeholder; real strings are not embedded here by default */
    gfo_out_puts(o, "0");
  } else {
    gfo_out_puts(o, "0");
  }
  gfo_out_puts(o, "}}");
}

int gfo_transpile_c_header(const gfo_ctx* ctx, gfo_out* out, const char* guard_name){
  gfo_u16 i;
  if(!ctx || !out) return GFO_ERR_RANGE;
  gfo_out_puts(out, "/* Auto-generated by gfo_transpile_c_header */\n");
  gfo_out_puts(out, "#ifndef "); gfo_out_puts(out, guard_name); gfo_out_puts(out, "\n#define "); gfo_out_puts(out, guard_name); gfo_out_puts(out, "\n\n");
  gfo_out_puts(out, "#include \"gfo_runtime.h\"\n\n");

  gfo_out_puts(out, "static const gfo_u16 gfo_bc_count = "); gfo_out_put_u32(out, ctx->bc.count); gfo_out_puts(out, ";\n");
  gfo_out_puts(out, "static const gfo_bc_ins gfo_bc_code[] = {\n");
  for(i=0;i<ctx->bc.count;i++){
    gfo_bc_ins ins = ctx->bc.code[i];
    gfo_out_puts(out, "  {");
    gfo_out_puts(out, ".op="); gfo_out_put_u32(out, (gfo_u32)ins.op);
    gfo_out_puts(out, ",.a="); gfo_out_put_u32(out, ins.a);
    gfo_out_puts(out, ",.b="); gfo_out_put_u32(out, ins.b);
    gfo_out_puts(out, ",.val="); emit_value(out, ins.val);
    gfo_out_puts(out, ",.text={0,0}");
    gfo_out_puts(out, "},\n");
  }
  gfo_out_puts(out, "};\n\n");

  /* symbol names debug table */
  gfo_out_puts(out, "static const gfo_u16 gfo_sym_count = "); gfo_out_put_u32(out, ctx->sym.count); gfo_out_puts(out, ";\n");
  gfo_out_puts(out, "static const char* gfo_sym_names[] = {\n");
  for(i=0;i<ctx->sym.count;i++){
    gfo_str nm = gfo_sym_name_by_id(&ctx->sym, i);
    gfo_out_puts(out, "  ");
    if(nm.ptr) gfo_out_put_str_lit(out, nm);
    else gfo_out_puts(out, "\"\"");
    gfo_out_puts(out, ",\n");
  }
  gfo_out_puts(out, "};\n\n");

  gfo_out_puts(out, "#endif\n");
  return GFO_OK;
}
